cssScreen:
.mono{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:12px}
.pad{padding:16px 24px 24px;display:flex;flex-direction:column;gap:16px}
.mpad{padding:12px 16px;display:flex;flex-direction:column;gap:12px}
.tb{border:1px solid var(--color-border-secondary);border-radius:12px;overflow:hidden}
table{width:100%;border-collapse:collapse}
td,th{padding:11px 16px;border-bottom:1px solid var(--color-border-secondary);text-align:left;font-size:12px}
tr:last-child td{border-bottom:0}
th{color:var(--color-text-secondary);font-weight:500;background:var(--color-bg-secondary)}
.chip{display:inline-block;font:500 12px/18px Inter;padding:2px 8px;border-radius:999px;background:var(--color-utility-neutral-100);color:var(--color-text-primary)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.span2{grid-column:span 2}
.card{border:1px solid var(--color-border-secondary);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:12px}
.card .h{font:600 14px/20px Inter}
dl{display:grid;grid-template-columns:110px 1fr;gap:6px 12px;margin:0;font-size:12px}
dt{color:var(--color-text-secondary)}
dd{margin:0}
.mrow{padding:12px 16px;border-bottom:1px solid var(--color-border-secondary);display:grid;grid-template-columns:1fr auto;gap:2px 8px}
.mrow .b{font-weight:600}
.mrow .sub{color:var(--color-text-secondary);font-size:12px;grid-column:1}
.mrow .chip{grid-row:1/span 2;grid-column:2;align-self:center}
.cta{height:52px;border:0;border-radius:999px;background:var(--color-action-primary);color:var(--color-text-inverse);font:600 16px Inter;margin-top:8px}
.bn{display:flex;align-items:center;gap:10px;padding:8px 24px;background:var(--color-bg-warning-primary);color:var(--color-text-warning-primary);border-bottom:1px solid var(--color-border-warning_subtle);font-size:12px}
.bn span{flex:1}
.bn b{font-weight:600}
